<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';require_user();$id=(int)get('id',0);$plan=dbone('SELECT * FROM plans WHERE id=? AND status=1',[$id]);if(!$plan) {flash('danger','Investment plan not found.');redirect('index.php?page=plans');}$u=current_user();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$amount=(float)post('amount',0);if($amount<(float)($plan['price']??0))flash('danger','Amount is below the plan minimum.');elseif($amount>(float)$u['balance'])flash('danger','Insufficient wallet balance.');else{db()->beginTransaction();try{$t=trx();dbq('UPDATE users SET balance=balance-? WHERE id=?',[$amount,user_id()]);dbq('INSERT INTO invest(user_id,plan_id,amount,profit,trx,status,started_at,ends_at) VALUES(?,?,?,?,?,1,NOW(),DATE_ADD(NOW(),INTERVAL ? DAY))',[user_id(),$plan['id'],$amount,0,$t,(int)($plan['duration']??30)]);dbq('INSERT INTO user_plans(user_id,plan_id,amount,status,activated_at,expires_at) VALUES(?,?,?,1,NOW(),DATE_ADD(NOW(),INTERVAL ? DAY))',[user_id(),$plan['id'],$amount,(int)($plan['duration']??30)]);db()->commit();flash('success','Investment created successfully.');redirect('index.php?page=investments');}catch(Throwable $e){db()->rollBack();flash('danger','Investment could not be created.');}}}$title='Invest';require __DIR__.'/includes/header.php';?><div class="card"><h1><?=e($plan['name']??'Investment')?></h1><p>Minimum: <?=e($plan['price']??0)?> · Duration: <?=e($plan['duration']??0)?> days · Return: <?=e($plan['percent']??$plan['profit']??0)?>%</p><form method="post"><?=csrf_field()?><div class="field"><label>Investment amount</label><input type="number" step="0.01" name="amount" min="<?=e($plan['price']??0)?>" required></div><br><button class="btn">Invest now</button></form></div><?php require __DIR__.'/includes/footer.php';?>